/** Step A34 research-only, four synchronized substeps per V3 tick.
 * Source-of-truth knots are generated by this physics step, not guessed from
 * future positions. Movement and W-prime are committed over identical intervals.
 * This adapter NEVER drives player races or stored results.
 */
import {continuousBicycleCollisionV3} from './continuousLateralResearchV3.mjs'
import {resolveEventTimeYieldV3} from './a2EventTimeYieldResearchV3.mjs'
import {resolveContactPriorityV3} from './a2CollisionPriorityResearchV3.mjs'
import {evaluateObservedPiecewisePairV3} from './a2NonlinearSweepAuditV3.mjs'
import {validateRoadScenarioV3} from './roadWidthLookaheadV3.mjs'
import {roadWattsRequiredV3} from '../../src/race-engine-v3/pelotonPowerBalanceV3.ts'
import {initializeEnergyBalanceResearchV3,boundRequestedSpeedByEnergyV3,commitAchievedSpeedEnergyV3} from '../../src/race-engine-v3/energyBalanceResearchV3.ts'
const check=(v,m)=>{if(!v)throw Error(m)}
const r6=v=>Math.round(v*1e6)/1e6
const nonnegative=v=>Number.isFinite(v)&&v>=0
function hit(a,b,g){return continuousBicycleCollisionV3(a,b,{longitudinal:1.8,lateral:g.lateralCollisionM})}
function segment(r,x,y){return {x0:r.meters,x1:x,y0:r.y,y1:y}}
export function initializeSubstepPhysicalResearchV3({riders,geometry,road={gradePercent:0},tickSeconds=10,substeps=4,conflictPolicy='symmetric_halving',diagnosticTrace=false}={}){
 const g=validateRoadScenarioV3(geometry)
 check(Array.isArray(riders)&&riders.length>=2&&riders.length<=32,'Invalid A34 roster count')
 check([2,4,5,10,20].includes(substeps)&&tickSeconds===10&&tickSeconds/substeps<=10,'Invalid A34 research step')
 check(['symmetric_halving','symmetric_trapezoid_motion','trapezoid_rear_priority','trapezoid_rear_corridor_guard','trapezoid_rear_corridor_strict','trapezoid_rear_corridor_leader','trapezoid_lane_priority','event_time_yield','event_time_fair','event_time_fair_normalized'].includes(conflictPolicy)&&typeof diagnosticTrace==='boolean','Invalid A38 trace option')
 check(road&&Number.isFinite(road.gradePercent)&&Math.abs(road.gradePercent)<=15,'Invalid A34 road grade')
 const ids=new Set(),maxY=(g.laneCount-1)*g.centerStepM
 const ready=riders.map(r=>{
  check(typeof r.riderId==='string'&&r.riderId.length>0&&!ids.has(r.riderId),'Duplicate/blank A34 rider')
  ids.add(r.riderId)
  check(nonnegative(r.meters)&&nonnegative(r.speedMps)&&r.speedMps<=20&&
   nonnegative(r.y)&&r.y<=maxY&&Number.isFinite(r.cpWatts)&&r.cpWatts>=100&&r.cpWatts<=500,
   'Invalid A34 rider state')
  return {riderId:r.riderId,meters:r6(r.meters),y:r6(r.y),speedMps:r6(r.speedMps),
   energy:initializeEnergyBalanceResearchV3({criticalWatts:r.cpWatts,wPrimeJoules:r.wPrimeJoules??18000})}
 }).sort((a,b)=>a.riderId.localeCompare(b.riderId))
 for(let i=0;i<ready.length;i++)for(let j=i+1;j<ready.length;j++){
  check(!hit(segment(ready[i],ready[i].meters,ready[i].y),segment(ready[j],ready[j].meters,ready[j].y),g),'Initially colliding A34 riders')
 }
 return {version:1,gate:'A34_OFFLINE_SUBSTEP_ONLY',officialWrites:0,sportingApproval:'NOT_APPROVED',
  geometry:structuredClone(geometry),road:structuredClone(road),tickSeconds,substeps,conflictPolicy,diagnosticTrace,tick:0,elapsedSeconds:0,
  riders:ready,metrics:{ticks:0,riderSubsteps:0,conflictPairChecks:0,collisionProposals:0,
    collisionAttenuationRounds:0,attenuatedRiderSubsteps:0,mechanicalJoules:0,observedPairs:0,
    endpointChordMisses:0,remainingPiecewiseOverlaps:0,yieldSelections:0,symmetricFallbacks:0,hardFallbacks:0,contactBoundaryFallbacks:0,
    contactSamples:0,contactFractionSum:0,physicalTieGroups:0,physicalTieParticipants:0,
    priorityRearYields:0,priorityEnteringYields:0,prioritySymmetricYields:0,priorityHardFallbacks:0,
    priorityCorridorGuards:0,priorityStalledGuards:0},lastTickTracks:[],lastTickConflictTrace:[]}
}
/** Freeze all currently submitted rider choices for this one research tick.
 * The next substep uses ONLY the state that was actually achieved before it.
 * If proposals conflict, synchronized riders attenuate BOTH forward and lateral
 * travel until each complete swept substep is clear. Never override a rival's
 * requested speed or lane, and do not interpret proposed targets as future truth.
 */
export function advanceSubstepPhysicalResearchV3(checkpoint,intents){
 check(checkpoint?.version===1&&checkpoint.gate==='A34_OFFLINE_SUBSTEP_ONLY'&&
  checkpoint.officialWrites===0&&checkpoint.sportingApproval==='NOT_APPROVED'&&
  Number.isInteger(checkpoint.tick)&&checkpoint.tick>=0&&
  ['symmetric_halving','symmetric_trapezoid_motion','trapezoid_rear_priority','trapezoid_rear_corridor_guard','trapezoid_rear_corridor_strict','trapezoid_rear_corridor_leader','trapezoid_lane_priority','event_time_yield','event_time_fair','event_time_fair_normalized'].includes(checkpoint.conflictPolicy),'Invalid A34 replay checkpoint')
 const state=structuredClone(checkpoint),g=validateRoadScenarioV3(state.geometry)
 check(Array.isArray(intents)&&intents.length===state.riders.length,'Missing A34 rider commands')
 const command=new Map(intents.map(c=>[c?.riderId,c]))
 check(command.size===state.riders.length,'Duplicate A34 rider command')
 const maximumY=(g.laneCount-1)*g.centerStepM,seconds=state.tickSeconds/state.substeps
 for(const r of state.riders){const c=command.get(r.riderId)
  check(c&&nonnegative(c.targetSpeedMps)&&c.targetSpeedMps<=20&&
   Number.isFinite(c.targetY)&&c.targetY>=0&&c.targetY<=maximumY&&
   Number.isFinite(c.steeringWatts??35)&&(c.steeringWatts??35)>=0&&(c.steeringWatts??35)<=75,
   'Invalid frozen A34 command')
 }
 const tracks=new Map(state.riders.map(r=>[r.riderId,[{t:0,x:r.meters,y:r.y}]]))
 const tickTrace=[]
 for(let step=1;step<=state.substeps;step++){
  const proposals=state.riders.map(r=>{
   const c=command.get(r.riderId)
   // Provisional acceleration/braking and lateral steering caps; not calibrated.
   const desire=Math.min(r.speedMps+.45*seconds,Math.max(r.speedMps-.85*seconds,c.targetSpeedMps))
   const change=Math.max(-.38*seconds,Math.min(.38*seconds,c.targetY-r.y))
   const y=r6(Math.max(0,Math.min(maximumY,r.y+change)))
   const turning=Math.abs(y-r.y)>1e-7
   const power=v=>roadWattsRequiredV3(v,83,.36,state.road)+(turning?(c.steeringWatts??35):0)
   const permitted=boundRequestedSpeedByEnergyV3(r.energy,seconds,desire,power)
   const speed=Math.max(0,Math.floor(Math.max(0,permitted-1e-7)*1e6)/1e6)
   const trapezoid=['symmetric_trapezoid_motion','trapezoid_rear_priority','trapezoid_rear_corridor_guard','trapezoid_rear_corridor_strict','trapezoid_rear_corridor_leader','trapezoid_lane_priority'].includes(state.conflictPolicy)
   // A43 opt-in: integrate the start/end velocity linearly across the physical
   // substep instead of applying the terminal velocity for its full duration.
   // Keep terminal speed separate from achieved average travel speed.
   return {riderId:r.riderId,
    forward:r6((trapezoid?(r.speedMps+speed)/2:speed)*seconds),
    terminalSpeedMps:speed,y,original:r,command:c}
  })
  // A43: observational-only proposal/contact trace, enabled explicitly.
  // Actual collision resolution, accepted paths and energy are not changed.
  let diagnosticProposal=null
  if(state.diagnosticTrace===true){
   const pairs=[]
   for(let i=0;i<proposals.length;i++)for(let j=i+1;j<proposals.length;j++){
    const a=proposals[i],b=proposals[j]
    if(hit(segment(a.original,r6(a.original.meters+a.forward),a.y),
      segment(b.original,r6(b.original.meters+b.forward),b.y),g))
     pairs.push([a.riderId,b.riderId])
   }
   diagnosticProposal={kind:'physical_substep',substep:step,dtSeconds:seconds,
    tickStartSeconds:state.elapsedSeconds,
    previewConflictPairs:pairs,
    previewConflictCount:pairs.length,
    proposals:proposals.map(p=>({riderId:p.riderId,
      x0:p.original.meters,y0:p.original.y,oldSpeedMps:p.original.speedMps,
      proposedMeters:p.forward,proposedY:p.y,
      requestedSpeedMps:p.command.targetSpeedMps,
      requestedY:p.command.targetY}))}
  }
  const event=['event_time_yield','event_time_fair','event_time_fair_normalized'].includes(state.conflictPolicy)?
   resolveEventTimeYieldV3(proposals,g,{diagnostics:state.diagnosticTrace===true,
    tiePolicy:state.conflictPolicy==='event_time_fair_normalized'?'physical_group_normalized':
     state.conflictPolicy==='event_time_fair'?'physical_group':'id_first'}):null
  const priority=state.conflictPolicy==='trapezoid_rear_priority'?
   resolveContactPriorityV3(proposals,g,{policy:'rear_priority',diagnostics:state.diagnosticTrace===true}):
   state.conflictPolicy==='trapezoid_rear_corridor_guard'?
   resolveContactPriorityV3(proposals,g,{policy:'rear_corridor_guard',diagnostics:state.diagnosticTrace===true}):
   state.conflictPolicy==='trapezoid_rear_corridor_strict'?
   resolveContactPriorityV3(proposals,g,{policy:'rear_corridor_strict',diagnostics:state.diagnosticTrace===true}):
   state.conflictPolicy==='trapezoid_rear_corridor_leader'?
   resolveContactPriorityV3(proposals,g,{policy:'rear_corridor_leader',diagnostics:state.diagnosticTrace===true}):
   state.conflictPolicy==='trapezoid_lane_priority'?
   resolveContactPriorityV3(proposals,g,{policy:'lane_entry_priority',diagnostics:state.diagnosticTrace===true}):null
  const scales=event?.scales??priority?.scales??new Map(proposals.map(p=>[p.riderId,1]))
  let resolved=event?.paths??priority?.paths??null
  if(event){
   if(event.diagnosticEvents)for(const x of event.diagnosticEvents)tickTrace.push({substep:step,...x})
   state.metrics.conflictPairChecks+=event.pairChecks
   state.metrics.collisionProposals+=event.collisionProposals
   state.metrics.collisionAttenuationRounds+=event.rounds
   state.metrics.yieldSelections+=event.yieldSelections
   state.metrics.symmetricFallbacks+=event.fallbacks
   state.metrics.hardFallbacks+=event.hardFallbacks
   state.metrics.contactBoundaryFallbacks+=event.contactBoundaryFallbacks
   state.metrics.contactSamples+=event.contactSamples
   state.metrics.contactFractionSum+=event.contactFractionSum
   state.metrics.physicalTieGroups+=event.physicalTieGroups
   state.metrics.physicalTieParticipants+=event.physicalTieParticipants
  }else if(priority){
   if(priority.diagnosticEvents)
    for(const event of priority.diagnosticEvents)tickTrace.push({substep:step,...event})
   state.metrics.conflictPairChecks+=priority.pairChecks
   state.metrics.collisionProposals+=priority.collisionProposals
   state.metrics.collisionAttenuationRounds+=priority.rounds
   state.metrics.priorityRearYields+=priority.rearYields
   state.metrics.priorityEnteringYields+=priority.enteringYields
   state.metrics.prioritySymmetricYields+=priority.symmetricYields
   state.metrics.priorityHardFallbacks+=priority.hardFallbacks
   state.metrics.priorityCorridorGuards+=priority.corridorGuardYields
   state.metrics.priorityStalledGuards+=priority.stalledGuardYields
  }else{
   for(let iteration=0;iteration<65;iteration++){
    const paths=proposals.map(p=>{
     const f=scales.get(p.riderId)
     return {...segment(p.original,r6(p.original.meters+p.forward*f),
       r6(p.original.y+(p.y-p.original.y)*f)),riderId:p.riderId}
    })
    const involved=new Set()
    for(let i=0;i<paths.length;i++)for(let j=i+1;j<paths.length;j++){
     state.metrics.conflictPairChecks++
     if(hit(paths[i],paths[j],g)){
      involved.add(paths[i].riderId);involved.add(paths[j].riderId)
      state.metrics.collisionProposals++
     }
    }
    if(involved.size===0){resolved=paths;break}
    check(iteration<64,'A34 no swept-safe synchronized movement')
    state.metrics.collisionAttenuationRounds++
    for(const id of involved)scales.set(id,scales.get(id)/2)
   }
  }
  check(resolved!==null,'A34 cannot resolve this substep')
  if(diagnosticProposal){
   diagnosticProposal.achieved=resolved.map(p=>({riderId:p.riderId,
    x1:p.x1,y1:p.y1,movementScale:scales.get(p.riderId)}))
   diagnosticProposal.attenuatedRiders=diagnosticProposal.achieved
    .filter(p=>p.movementScale<1).map(p=>p.riderId)
   tickTrace.push(diagnosticProposal)
  }
  const result=new Map(resolved.map(p=>[p.riderId,p]))
  const proposalById=new Map(proposals.map(p=>[p.riderId,p]))
  state.riders=state.riders.map(old=>{
   const p=result.get(old.riderId),c=command.get(old.riderId)
   const achievedSpeed=(p.x1-old.meters)/seconds
   check(achievedSpeed>=-1e-7&&achievedSpeed<=20+1e-7,'A34 movement outside allowed speed')
   const turning=Math.abs(p.y1-old.y)>1e-7
   const power=v=>roadWattsRequiredV3(v,83,.36,state.road)+(turning?(c.steeringWatts??35):0)
   const energy=commitAchievedSpeedEnergyV3(old.energy,seconds,Math.max(0,achievedSpeed),power)
   check(energy.remainingWPrimeJoules>=0&&energy.seconds===state.elapsedSeconds+seconds*step,
    'A34 energy and movement clock diverged')
   state.metrics.mechanicalJoules+=energy.cumulativeMechanicalJoules-old.energy.cumulativeMechanicalJoules
   state.metrics.riderSubsteps++
   state.metrics.attenuatedRiderSubsteps+=Number(scales.get(old.riderId)<1)
   tracks.get(old.riderId).push({t:step/state.substeps,x:p.x1,y:p.y1})
   const clearMotion=['symmetric_trapezoid_motion','trapezoid_rear_priority','trapezoid_rear_corridor_guard','trapezoid_rear_corridor_strict','trapezoid_rear_corridor_leader','trapezoid_lane_priority'].includes(state.conflictPolicy)&&
    scales.get(old.riderId)>=1-1e-10
   const endSpeed=clearMotion?proposalById.get(old.riderId).terminalSpeedMps:achievedSpeed
   return {...old,meters:p.x1,y:p.y1,speedMps:r6(endSpeed),energy}
  })
 }
 const sorted=state.riders.slice().sort((a,b)=>a.riderId.localeCompare(b.riderId))
 const records=sorted.map(r=>({riderId:r.riderId,knots:tracks.get(r.riderId)}))
 for(let i=0;i<records.length;i++)for(let j=i+1;j<records.length;j++){
  const comparison=evaluateObservedPiecewisePairV3(records[i].knots,records[j].knots,
   {longitudinal:1.8,lateral:g.lateralCollisionM})
  state.metrics.observedPairs++
  state.metrics.endpointChordMisses+=Number(comparison.missedByEndpointChord)
  state.metrics.remainingPiecewiseOverlaps+=Number(comparison.piecewiseObservedCollision)
  check(!comparison.piecewiseObservedCollision,'A34 produced unsafe piecewise motion')
 }
 state.tick++;state.elapsedSeconds+=state.tickSeconds;state.metrics.ticks++
 state.lastTickTracks=records
 state.lastTickConflictTrace=tickTrace
 return state
}
